mapper.select:
select id, verifier_member_id, topic_id, risk_type, verification_rate, paid_count,
       verified_count, one_minute_count, status, idempotency_key, create_time, update_time
from verification_review

    status = #{status}
    and topic_id = #{topicId}
    and verifier_member_id = #{verifierMemberId}

order by status asc, create_time desc

mapper.update:
update verification_review
set status = #{status}, update_time = now()
where id = #{id}
  and topic_id = #{topicId}
  and status = 0
